int main(int argc,char** argv){try{if(argc!=3)throw std::runtime_error("Usage: player-animation-tests constants sha");std::ifstream input(argv[1],std::ios::binary|std::ios::ate);check(bool(input)&&input.tellg()==88,"Constants extent");std::array<std::uint8_t,88> bytes{};input.seekg(0);check(bool(input.read(reinterpret_cast<char*>(bytes.data()),bytes.size()))&&input.peek()==std::char_traits<char>::eof(),"Constants read");const auto constants=value<pt::Constants>(pt::Constants::decode(bytes,{argv[2],"d4191ea404df1e9ade8fb401983e3497699dae5aa994937f7859c43f84403435"}));run(constants);std::cout<<"{\"status\":\"passed\",\"checks\":"<<checks<<"}\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
